Query Final:
SELECT FILTERREPORTINGPERIOD as "Reporting Period",   dg.regionname as region, SUM(fasf.paymentnetamount) AS "payment amount" from l2_reporting_sch_demo.dimgeography dg inner join l2_reporting_sch_demo.factaccountsnapshot_final fasf on dg.geographykey=fasf.geographykey
AND dg.periodid = fsaf.reportingperiodkey
GROUP BY  FILTERREPORTINGPERIOD,    dg.regionname;

